<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { Archive, CheckCheck, Database, Download, HardDrive, LogOut, PanelTopOpen, Save, ShieldCheck } from 'lucide-vue-next'
import Pager from '../components/Pager.vue'
import LanSettings from '../components/LanSettings.vue'
import { api, dateTimeLabel, loadProjects, messageOf, notify, openCompactWindow, query, ui } from '../api'
import type { Backup, Page } from '../types'
interface SystemInfo {data_dir:string;executable:string;platform:string;gjb_level:string;backup:{last_success:string;last_error:string;checked_at:string;in_progress:boolean;warning:string;available_bytes:number;archive_name:string};migration_note:string}
const info=ref<SystemInfo>();const policy=reactive({backup_keep_count:'30',backup_max_mb:'0',backup_auto:'1'}),policySaving=ref(false),planAction=ref('relocate'),targetDir=ref(''),restoreName=ref(''),planning=ref(false),plan=ref<{commands:string[];notes:string[];source_dir:string;target_dir?:string;backup_path?:string}>(),planError=ref('')
const emit=defineEmits<{changed:[]}>()
const lanSettings=ref<{canLeave:()=>boolean}>()
const desktopDefault=ref(true),desktopSaving=ref(false)
const operator=ref(''),version=ref(''),backups=ref<Backup[]>([]),backupTotal=ref(0),offset=ref(0),error=ref(''),saving=ref(false),backing=ref(false),checking=ref(false),demoing=ref(false),stopping=ref(false),stopped=ref(false),audit=ref<{ok:boolean;total:number;broken_at?:string}>();const limit=20
async function loadBackups(){const data=await api<Page<Backup>>(`/api/backups?${query({limit,offset:offset.value})}`);backups.value=data.items;backupTotal.value=data.total}
async function refreshInfo(){info.value=await api<SystemInfo>('/api/system/info')}
onMounted(async()=>{try{const [settings,health]=await Promise.all([api<Record<string,string>>('/api/settings'),api<{version:string}>('/api/health')]);operator.value=settings.operator;desktopDefault.value=settings.desktop_default!=='0';version.value=health.version;Object.assign(policy,{backup_keep_count:settings.backup_keep_count||'30',backup_max_mb:settings.backup_max_mb||'0',backup_auto:settings.backup_auto||'1'});await Promise.all([loadBackups(),refreshInfo()])}catch(e){error.value=messageOf(e)}})
async function saveDesktopPreference(){desktopSaving.value=true;error.value='';try{await api('/api/settings',{method:'PUT',body:JSON.stringify({desktop_default:desktopDefault.value?'1':'0'})});notify('桌面入口偏好已保存，下次启动生效')}catch(e){error.value=messageOf(e)}finally{desktopSaving.value=false}}
async function savePolicy(){policySaving.value=true;error.value='';try{await api('/api/settings',{method:'PUT',body:JSON.stringify({...policy,backup_keep_count:String(policy.backup_keep_count),backup_max_mb:String(policy.backup_max_mb)})});notify('备份策略已保存，新包验证成功后生效');await refreshInfo()}catch(e){error.value=messageOf(e)}finally{policySaving.value=false}}
async function generatePlan(){planning.value=true;planError.value='';plan.value=undefined;try{plan.value=await api('/api/system/maintenance-plan',{method:'POST',body:JSON.stringify({action:planAction.value,...(planAction.value==='relocate'?{target_dir:targetDir.value}:{backup_name:restoreName.value})})})}catch(e){planError.value=messageOf(e)}finally{planning.value=false}}
async function copyPlan(){if(!plan.value)return;try{await navigator.clipboard.writeText(plan.value.commands.join('\n'));notify('维护指令已复制')}catch{planError.value='浏览器不允许复制，请选中下方指令手动复制。'}}
async function save(){saving.value=true;error.value='';try{await api('/api/settings',{method:'PUT',body:JSON.stringify({operator:operator.value,setup_completed:'1'})});ui.operator=operator.value;notify('操作人已保存')}catch(e){error.value=messageOf(e)}finally{saving.value=false}}
async function backup(){backing.value=true;error.value='';try{await api('/api/backups',{method:'POST',body:'{}'});notify('备份已创建');offset.value=0;await Promise.all([loadBackups(),refreshInfo()])}catch(e){error.value=messageOf(e)}finally{backing.value=false}}
async function verify(){checking.value=true;error.value='';try{audit.value=await api('/api/audit/verify');notify(audit.value?.ok?'审计链校验通过':'审计链校验发现异常',!audit.value?.ok)}catch(e){error.value=messageOf(e)}finally{checking.value=false}}
async function demo(){if(!window.confirm('在当前空工作空间中加载示例项目、任务、记录和问题？已有业务数据时不会执行。'))return;demoing.value=true;error.value='';try{await api('/api/demo',{method:'POST',body:'{}'});await loadProjects();notify('示例数据已加载，可以开始体验');emit('changed')}catch(e){error.value=messageOf(e)}finally{demoing.value=false}}
async function shutdown(){if(!window.confirm('确定退出 ProjNote 并停止本机服务？尚未保存到数据库的内容仅在当前浏览器草稿中保留。'))return;stopping.value=true;error.value='';try{await api('/api/system/shutdown',{method:'POST',body:'{}'});stopped.value=true}catch(e){error.value=messageOf(e)}finally{stopping.value=false}}
async function page(next:number){offset.value=next;try{await loadBackups()}catch(e){error.value=messageOf(e)}}
defineExpose({canLeave:()=>!saving.value&&!planning.value&&!backing.value&&!stopping.value&&(lanSettings.value?.canLeave()??true)})
function size(value:number){return value<1024?`${value} B`:value<1024*1024?`${(value/1024).toFixed(1)} KB`:`${(value/1024/1024).toFixed(1)} MB`}
</script>
<template><div class="page-heading"><div><h1>设置与备份</h1><p class="page-description">工作空间由你掌管，重要资料定期留一份副本。</p></div><span class="version-label" v-if="version">ProjNote {{version}}</span></div><div v-if="error" class="error-banner" role="alert">{{error}}</div><div v-if="stopped" class="shutdown-state surface"><CheckCheck :size="36"/><h2>本机服务已停止</h2><p>可以关闭此页面。下次启动 ProjNote 后即可继续使用。</p></div><div v-else class="settings-layout"><section class="surface settings-panel"><div class="section-heading"><h2>工作空间</h2><HardDrive :size="18"/></div><div class="directory-explainer settings-directory"><strong>当前数据目录</strong><code>{{info?.data_dir||'正在读取…'}}</code><p>数据库、图片、浏览器草稿的数据集标识均与当前工作空间关联。浏览器草稿只在本浏览器中保留；数据库和附件在此目录持久保存。</p><span class="standard-label">已确认：GJB5000B 二级，证据模板待核对。</span></div><form class="settings-body" @submit.prevent="save"><label>操作人<input v-model="operator" required maxlength="80" placeholder="姓名或称呼"/></label><p class="input-hint">记录在问题流转和审计日志中，便于追溯每次操作。</p><button class="button primary small" :disabled="saving"><Save :size="15"/>{{saving?'正在保存…':'保存设置'}}</button></form><div class="settings-block"><div class="setting-icon"><Database :size="20"/></div><div><h3>从示例了解工作流程</h3><p>加载一组示例项目、任务、现场记录和问题，仅支持空工作空间。</p><button class="button subtle small" :disabled="demoing" @click="demo">{{demoing?'正在加载…':'加载示例数据'}}</button></div></div><div class="settings-block"><div class="setting-icon"><ShieldCheck :size="20"/></div><div><h3>操作审计校验</h3><p>核对审计记录的连续性，检查操作历史是否完整。</p><button class="button subtle small" :disabled="checking" @click="verify">{{checking?'正在校验…':'校验审计链'}}</button><p v-if="audit" class="audit-result" :class="{invalid:!audit.ok}" role="status">{{audit.ok?`校验通过，共 ${audit.total} 条审计记录`:`发现异常，位置：${audit.broken_at||'未知'}`}}</p></div></div><div class="settings-block"><div class="setting-icon"><PanelTopOpen :size="20"/></div><div><h3>桌面便签</h3><p>正常启动只显示固定在右下角的单箭头入口；点击打开原生便签并隐藏图标，点击窗口内的 × 或按 Alt+F4 收回入口。入口不拖动；右键可打开完整工作台或退出入口。任务需选择所属项目。</p><form class="desktop-startup-preference" @submit.prevent="saveDesktopPreference"><label class="checkbox-label"><input v-model="desktopDefault" type="checkbox"/>启动时显示桌面入口</label><button class="text-button" :disabled="desktopSaving">{{desktopSaving?'正在保存…':'保存启动偏好'}}</button><p class="input-hint">下次启动生效，不影响正在编辑的便签。</p></form><div class="row-actions compact-setting-actions"><button class="button subtle small" @click="openCompactWindow">打开桌面便签</button><a class="text-button" href="#/compact">网页简洁版（可选）</a></div></div></div><div class="settings-block"><div class="setting-icon"><LogOut :size="20"/></div><div><h3>退出 ProjNote</h3><p>只关闭浏览器不会停止服务。结束本次工作时，可在这里退出。</p><button class="button subtle small" :disabled="stopping" @click="shutdown">{{stopping?'正在退出…':'退出并停止服务'}}</button></div></div></section><section class="surface settings-panel"><div class="section-heading"><h2>数据备份 <span class="count">{{backupTotal}}</span></h2><button class="button primary small" :disabled="backing" @click="backup"><Archive :size="15"/>{{backing?'正在创建…':'创建备份'}}</button></div><div v-if="info" class="backup-health"><div><span class="local-dot" :class="{unhealthy:info.backup.last_error}"/><strong>{{info.backup.in_progress?'备份进行中':info.backup.last_error?'备份需要处理':info.backup.last_success?'最近备份成功':'等待首次备份'}}</strong><button class="text-button" @click="refreshInfo().catch(e=>error=messageOf(e))">刷新状态</button></div><p>最近成功：{{info.backup.last_success?dateTimeLabel(info.backup.last_success):'尚无'}}　可用空间：{{size(info.backup.available_bytes)}}</p><p v-if="info.backup.last_error" class="health-error">{{info.backup.last_error}}</p><p v-if="info.backup.warning">{{info.backup.warning}}</p></div><form class="backup-policy" @submit.prevent="savePolicy"><h3>自动备份与保留策略</h3><label class="checkbox-label"><input v-model="policy.backup_auto" type="checkbox" true-value="1" false-value="0"/>每日自动备份</label><div class="form-row"><label>最多保留份数<input v-model="policy.backup_keep_count" type="number" min="2" max="365" required/></label><label>备份容量预算（MB）<input v-model="policy.backup_max_mb" type="number" min="0" max="1000000" required/></label></div><p class="input-hint">容量 0 表示不限制；非零至少 100 MB。新包验证成功后才清理旧包，受保护的回滚点与唯一恢复点会保留。</p><button class="button subtle small" :disabled="policySaving">{{policySaving?'正在保存…':'保存备份策略'}}</button></form><div class="backup-description"><p>备份包含数据库与附件。创建后可下载到其他磁盘，保留独立副本。</p><span class="input-hint">恢复备份需先退出服务，再用启动程序的 --restore 参数执行。</span></div><div v-if="!backups.length" class="empty-state compact"><Archive :size="32"/><h3>还没有备份</h3><p>完成重要工作后，创建一份资料副本。</p><button class="button subtle small" :disabled="backing" @click="backup">创建第一份备份</button></div><ul v-else class="backup-list"><li v-for="b in backups" :key="b.name"><div class="backup-file"><Archive :size="22"/><div><strong>{{b.name}}</strong><span v-if="b.protected" class="protected-backup">回滚点，自动清理保留</span><span>{{dateTimeLabel(b.created_at)}}　{{size(b.size)}}</span></div></div><a class="button subtle small" :href="`/api/backups/${encodeURIComponent(b.name)}/download`" :download="b.name" :aria-label="`下载备份 ${b.name}`"><Download :size="16"/>下载</a></li></ul><Pager :offset="offset" :limit="limit" :total="backupTotal" @change="page"/></section><section class="surface maintenance-panel"><div class="section-heading"><h2>迁移与恢复向导</h2><span class="muted">生成停服指令</span></div><form class="settings-body" @submit.prevent="generatePlan"><p class="input-hint">网页只生成维护步骤。先保存工作并停止服务，再在本机终端执行；运行期间不会替换数据库，原目录保留。</p><label>维护操作<select v-model="planAction" @change="plan=undefined"><option value="relocate">迁移到新数据目录</option><option value="restore">从已有备份恢复</option></select></label><label v-if="planAction==='relocate'">目标目录绝对路径<input v-model="targetDir" required placeholder="输入为空或尚不存在的绝对目录路径"/></label><label v-else>备份文件<select v-model="restoreName" required><option value="" disabled>请选择备份</option><option v-for="b in backups" :key="b.name" :value="b.name">{{b.name}}</option></select></label><p v-if="planError" class="form-error" role="alert">{{planError}}</p><button class="button primary small" :disabled="planning">{{planning?'正在校验…':'校验并生成维护步骤'}}</button></form><div v-if="plan" class="maintenance-plan"><h3>按顺序执行</h3><ol><li v-for="note in plan.notes" :key="note">{{note}}</li></ol><pre tabindex="0">{{plan.commands.join('\n')}}</pre><button class="button subtle small" @click="copyPlan">复制全部指令</button></div></section><LanSettings ref="lanSettings"/><section class="surface about-panel" aria-labelledby="about-title"><div class="section-heading"><h2 id="about-title">关于 ProjNote</h2></div><dl class="about-details"><div><dt>应用</dt><dd>ProjNote 项目管理工作台</dd></div><div><dt>版本</dt><dd>{{version||'正在读取…'}}</dd></div><div><dt>作者</dt><dd>zhoutao</dd></div><div><dt>公司</dt><dd>zkhx</dd></div></dl></section></div></template>

<style scoped>.about-panel{grid-column:1/-1}.about-details{margin:0;padding:18px 22px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px 30px}.about-details>div{display:flex;gap:18px;min-width:0}.about-details dt{color:var(--muted);font-size:12px;min-width:30px}.about-details dd{margin:0;font-size:13px;overflow-wrap:anywhere}@media(max-width:600px){.about-details{grid-template-columns:1fr}}</style>
